--- frontends/studio-mfe/src/tools/text-to-speech/EnhancedVoiceSampleSelector.tsx (415 lines) ---
/**
 * EnhancedVoiceSampleSelector — the Qwen3-TTS voice-sample picker for the
 * Text to Speech tool (#1066, Epic #1064). Fetches the org's personal +
 * org-shared voice samples (`GET /api/v1/studio/voice-samples` via
 * `useVoiceSamples`) and lets the user pick one, writing the choice back to
 * the host via `onSelect`.
 *
 * The `studio.voice_samples` table ships empty until a future upload
 * ticket lands (Epic #1064 decision) — the empty state is a first-class,
 * expected state (AC: "If no voice samples exist for Qwen3-TTS, selector
 * shows empty state with a link to Settings > Voice Samples"), not a
 * placeholder. The link resolves to the real Coming-Soon placeholder route
 * already wired in `StudioApp.tsx` at `settings/voice-samples`.
 *
 * A `<fieldset>` + `<legend>` wraps every state (loading/error/empty/ready)
 * so the group has one stable accessible name throughout — mirrors the
 * fieldset/legend a11y convention used elsewhere in this MFE's forms
 * (real `<label>`/`aria-describedby`, §7 of the hard a11y rules).
 *
 * An "Upload new" affordance sits inside the same fieldset, below every
 * state (#1065-1070, step 11): it layers `VoiceSampleUploadModal` on top of
 * the host tool without navigating away or unmounting anything. On a
 * successful upload it closes the modal, auto-selects the new sample via
 * `onSelect`, and calls `useVoiceSamples`'s `retry()` to refetch the list —
 * the modal's own success Toast is the only user-facing confirmation, so
 * this component does not show a second one.
 *
 * Empty and error states each carry a real "Upload a sample" action (same
 * modal, via `setUploadOpen(true)`) alongside their existing secondary
 * action, per design.md sections 06-08's "two real next steps" and
 * "don't leave a dead end on failure" guidance — this component has a
 * single flat list (no Library/Documents tabs like the design board's
 * source composition), so the fix stays scoped to what actually exists
 * here: honest, non-overstated copy plus a working way forward.
 *
 * No audition/"Hear sample" affordance on the ready/chosen row: `VoiceSample`
 * (the list shape returned by `GET /voice-samples`) carries no playable URL
 * or `filesDocumentId` — only the create-response shape does — and no
 * `Hear sample` component exists elsewhere in this MFE to reuse. Adding one
 * here would mean inventing playback plumbing nobody asked for; tracked
 * separately rather than improvised in this pass.
 *
 * Delete (soft, via `DELETE /api/v1/studio/voice-samples/{id}`) is offered
 * ONLY in the expanded radiogroup, next to each sample the caller OWNS —
 * mirrors `VoiceSamplesSettingsRoute`'s rule that "can see it" (an org_shared
 * sample owned by someone else) must not imply "can delete it" (the svc
 * returns NOT_FOUND for a non-owner). Goes through the same AlertDialog
 * confirm pattern as the settings page. If the deleted sample was the one
 * currently selected, `onSelect("")` clears it — otherwise Generate would
 * stay enabled against a selection that can no longer resolve, and the job
 * would only fail once it reached the worker.
 *
 * cog-* tokens only (auto-adapt to dark mode via CSS variables).
 */

import { type JSX, useEffect, useId, useState } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { AlertDialog, Badge, Button, cn, RadioGroup } from "@omnicore-platform/ui";
import { Check } from "@omnicore-platform/ui/icons";
import { useVoiceSamples } from "../../lib/useVoiceSamples";
import {
  deleteVoiceSample,
  type CreatedVoiceSample,
  type VoiceSample,
} from "../../api/voiceSamples";
import { VoiceSampleUploadModal } from "../voice-samples/VoiceSampleUploadModal";

export interface EnhancedVoiceSampleSelectorProps {
  /** The currently-selected voice sample's id, or undefined if none chosen. */
  readonly value: string | undefined;
  readonly onSelect: (id: string) => void;
  readonly disabled?: boolean;
  /** Test/injection seam — mirrors this MFE's loader-prop convention. Defaults to the real `listVoiceSamples`. */
  readonly loader?: () => Promise<readonly VoiceSample[]>;
}

const QUALITY_LABELS: Readonly<Record<string, () => string>> = {
  high: m.studio_tts_voice_sample_quality_high,
  medium: m.studio_tts_voice_sample_quality_medium,
  low: m.studio_tts_voice_sample_quality_low,
};

function qualityLabel(quality: string): string {
  const known = QUALITY_LABELS[quality];
  return known ? known() : quality;
}

function sampleMeta(sample: VoiceSample): string {
  return m.studio_tts_voice_sample_meta({
    language: sample.language,
    quality: qualityLabel(sample.quality),
    duration: m.studio_tts_voice_sample_duration_value({
      seconds: sample.durationSeconds.toFixed(1),
    }),
  });
}

export function EnhancedVoiceSampleSelector({
  value,
  onSelect,
  disabled = false,
  loader,
}: EnhancedVoiceSampleSelectorProps): JSX.Element {
  const groupId = useId();
  const state = useVoiceSamples({ loader });
  const [uploadOpen, setUploadOpen] = useState(false);
  // The sample awaiting delete confirmation, offered only in the expanded
  // list and only for samples the caller owns (mirrors
  // VoiceSamplesSettingsRoute's rule — the svc returns NOT_FOUND for anyone
  // else's sample, so a button that always fails would be worse than none).
  const [pendingDelete, setPendingDelete] = useState<VoiceSample | null>(null);
  const [deleteBusy, setDeleteBusy] = useState(false);
  const [deleteFailed, setDeleteFailed] = useState(false);
  // Starts collapsed if a sample is already selected on mount (e.g. re-opening
  // the tool with a previously-chosen sample); re-synced below whenever
  // `value` transitions to/from undefined (a fresh selection or a clear).
  const [isExpanded, setIsExpanded] = useState(() => value === undefined);

  useEffect(() => {
    setIsExpanded(value === undefined);
  }, [value]);

  function handleCreated(sample: CreatedVoiceSample): void {
    setUploadOpen(false);
    onSelect(sample.id);
    state.retry();
  }

  function openDeleteConfirm(sample: VoiceSample): void {
    setPendingDelete(sample);
    setDeleteFailed(false);
  }

  function closeDeleteConfirm(): void {
    if (deleteBusy) return;
    setPendingDelete(null);
    setDeleteFailed(false);
  }

  async function confirmDelete(): Promise<void> {
    if (pendingDelete === null) return;
    setDeleteBusy(true);
    setDeleteFailed(false);
    try {
      await deleteVoiceSample(pendingDelete.id);
      // Clear a stale selection: without this, a deleted-but-still-selected
      // id lingers in the host tool's formData, Generate stays enabled
      // against a selection that can no longer resolve, and the job only
      // fails once it reaches the worker.
      if (value === pendingDelete.id) {
        onSelect("");
      }
      setPendingDelete(null);
      state.retry();
    } catch {
      // Stay open on failure — the specific reason is deliberately not
      // surfaced (the BFF's 404 covers unknown/already-deleted/not-yours on
      // purpose, so a reason-specific message would be guesswork).
      setDeleteFailed(true);
    } finally {
      setDeleteBusy(false);
    }
  }

  return (
    <fieldset className="flex flex-col gap-cog-2 rounded-md border border-cog-border p-cog-3">
      <legend className="px-cog-1 text-body-sm font-medium text-cog-text-primary">
        {m.studio_tts_voice_sample_label()}
      </legend>

      {state.tag === "loading" && (
        <p role="status" className="text-body-sm text-cog-text-secondary">
          {m.studio_tts_voice_sample_loading()}
        </p>
      )}

      {state.tag === "error" && (
        <div className="flex flex-col gap-cog-2">
          <div className="flex flex-wrap items-center gap-cog-2">
            <p role="alert" className="text-body-sm text-cog-danger-600 dark:text-cog-danger-dark">
              {m.studio_tts_voice_sample_error()}
            </p>
            <Button type="button" variant="secondary" size="sm" onClick={state.retry}>
              {m.studio_tts_voice_sample_retry_btn()}
            </Button>
            {/* A broken list isn't a dead end — Upload still works even when
                the fetch that populates the list failed. */}
            <Button type="button" variant="secondary" size="sm" onClick={() => setUploadOpen(true)}>
              {m.studio_tts_voice_sample_upload_sample_cta()}
            </Button>
          </div>
          <p className="text-body-sm text-cog-text-secondary">
            {m.studio_tts_voice_sample_error_hint()}
          </p>
        </div>
      )}

      {state.tag === "empty" && (
        <div className="flex flex-col gap-cog-2">
          <p className="text-body-sm font-medium text-cog-text-primary">
            {m.studio_tts_voice_sample_empty_title()}
          </p>
          <p className="text-body-sm text-cog-text-secondary">
            {m.studio_tts_voice_sample_empty_body()}
          </p>
          <div className="flex flex-wrap items-center gap-cog-2">
            {/* No link to a separate settings page — every action here must
                resolve in a modal layered on this same page. A prior
                revision linked out to /studio/settings/voice-samples
                (a Coming-Soon placeholder anyway); that broke the "stay on
                this page" contract every other state in this component
                already honors. */}
            <Button type="button" variant="primary" size="sm" onClick={() => setUploadOpen(true)}>
              {m.studio_tts_voice_sample_upload_sample_cta()}
            </Button>
          </div>
        </div>
      )}

      {state.tag === "ready" && !isExpanded && (() => {
        const chosen = state.samples.find((sample) => sample.id === value);
        // Guard against a transient gap between selecting a brand-new upload
        // (value already updated) and the list finishing its refetch (sample
        // not in `state.samples` yet) — fall through to the expanded list
        // rather than flashing an empty control.
        if (!chosen) return null;
        return (
          <div className="flex items-center gap-cog-2 rounded-md border border-cog-blue-600 bg-cog-blue-50 p-cog-2 dark:bg-cog-blue-900/20">
            <Check aria-hidden="true" className="h-cog-4 w-cog-4 shrink-0 text-cog-blue-600" />
            <span className="sr-only">{m.studio_tts_voice_sample_selected_sr()}</span>
            <span className="flex min-w-cog-0 flex-1 flex-col">
              <span className="text-body-sm font-medium text-cog-text-primary">{chosen.name}</span>
              <span className="text-body-sm text-cog-text-tertiary">{sampleMeta(chosen)}</span>
            </span>
            {chosen.isOrgShared && (
              <Badge variant="neutral">{m.studio_tts_voice_sample_shared_badge()}</Badge>
            )}
            <Button
              type="button"
              variant="ghost"
              size="sm"
              disabled={disabled}
              onClick={() => setIsExpanded(true)}
            >
              {m.studio_tts_voice_sample_change_btn()}
            </Button>
          </div>
        );
      })()}

      {state.tag === "ready" && (isExpanded || state.samples.every((sample) => sample.id !== value)) && (
        <RadioGroup.Root
          aria-label={m.studio_tts_voice_sample_label()}
          className="flex flex-col gap-cog-2"
          // Radix drives selection off a string `value`; "" is the honest
          // "nothing chosen yet" sentinel (no sample id is ever empty), and
          // it matches what `confirmDelete` already writes back through
          // `onSelect("")` when the selected sample is deleted.
          value={value ?? ""}
          disabled={disabled}
          onValueChange={onSelect}
        >
          {state.samples.map((sample) => {
            const itemId = `${groupId}-${sample.id}`;
            const isSelected = value === sample.id;
            return (
              // The row is a plain container, not a <label>: the delete
              // Button lives beside the radio, and a <button> nested inside
              // another <button> is invalid. The radio itself spans the whole
              // row minus that Button, so clicking the name/meta still selects
              // — the same reach the old label-wrapping gave — while the
              // delete Button is a sibling that can never double-fire a
              // selection on its way through.
              <div
                key={sample.id}
                className={cn(
                  "flex items-center gap-cog-2 rounded-md border p-cog-2",
                  isSelected
                    ? "border-cog-blue-600 bg-cog-blue-50 dark:bg-cog-blue-900/20"
                    : "border-cog-border",
                )}
              >
                <RadioGroup.Item
                  id={itemId}
                  value={sample.id}
                  className="group flex min-w-cog-0 flex-1 items-center gap-cog-2 text-start disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {/* The drawn radio pill. `RadioGroup.Item` only auto-renders
                      its own Indicator when no children are passed, and `ui`
                      exports no Indicator part, so the selected dot is drawn
                      from the same `isSelected` this row already computes. */}
                  <span
                    aria-hidden="true"
                    className={cn(
                      "inline-flex h-cog-4 w-cog-4 shrink-0 items-center justify-center rounded-pill border",
                      // Same disabled treatment the shared primitive draws on
                      // its own default pill — a real token change, not an
                      // opacity-only dim.
                      "group-disabled:border-cog-border group-disabled:bg-cog-surface-muted",
                      isSelected ? "border-cog-blue-600" : "border-cog-border",
                    )}
                  >
                    {isSelected && (
                      <span className="block h-cog-2 w-cog-2 rounded-pill bg-cog-blue-600" />
                    )}
                  </span>
                  <span className="flex min-w-cog-0 flex-1 flex-col">
                    <span className="text-body-sm font-medium text-cog-text-primary">
                      {sample.name}
                    </span>
                    <span className="text-body-sm text-cog-text-tertiary">{sampleMeta(sample)}</span>
                  </span>
                  {isSelected && (
                    <>
                      <Check aria-hidden="true" className="h-cog-4 w-cog-4 shrink-0 text-cog-blue-600" />
                      <span className="sr-only">{m.studio_tts_voice_sample_selected_sr()}</span>
                    </>
                  )}
                </RadioGroup.Item>
                {sample.isOrgShared && (
                  <Badge variant="neutral">{m.studio_tts_voice_sample_shared_badge()}</Badge>
                )}
                {sample.isOwnedByMe && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    disabled={disabled}
                    aria-label={m.studio_voice_sample_delete_aria({ name: sample.name })}
                    onClick={() => openDeleteConfirm(sample)}
                  >
                    {m.studio_voice_sample_delete_btn()}
                  </Button>
                )}
              </div>
            );
          })}
        </RadioGroup.Root>
      )}

      {pendingDelete !== null && (
        <AlertDialog.Root
          open
          onOpenChange={(next) => {
            if (!next) closeDeleteConfirm();
          }}
        >
          <AlertDialog.Content className="w-full max-w-cog-modal rounded-xl border border-cog-border bg-cog-surface shadow-cog-e5 outline-none dark:border-cog-border-dark-emphasized">
            <div className="border-b border-cog-divider px-cog-5 py-cog-4">
              <AlertDialog.Title className="text-heading-sm text-cog-text-primary">
                {m.studio_voice_sample_delete_confirm_title()}
              </AlertDialog.Title>
            </div>
            <div className="px-cog-5 py-cog-4">
              <AlertDialog.Description className="text-body-sm text-cog-text-secondary">
                {m.studio_voice_sample_delete_confirm_body({ name: pendingDelete.name })}
              </AlertDialog.Description>
              {deleteFailed && (
                <p
                  role="alert"
                  className="mt-cog-3 text-body-sm text-cog-danger-600 dark:text-cog-danger-dark"
                >
                  {m.studio_voice_sample_delete_error()}
                </p>
              )}
              <div className="mt-cog-5 flex flex-wrap items-center justify-end gap-cog-2">
                <AlertDialog.Cancel disabled={deleteBusy} className="px-cog-4 text-body-sm">
                  {m.studio_voice_sample_delete_cancel_btn()}
                </AlertDialog.Cancel>
                <AlertDialog.Action
                  variant="danger"
                  disabled={deleteBusy}
                  aria-busy={deleteBusy}
                  className="px-cog-4 text-body-sm"
                  onClick={(event) => {
                    event.preventDefault();
                    void confirmDelete();
                  }}
                >
                  {m.studio_voice_sample_delete_confirm_cta()}
                </AlertDialog.Action>
              </div>
            </div>
          </AlertDialog.Content>
        </AlertDialog.Root>
      )}

      {/* Empty/error already carry their own "Upload a sample" CTA above —
          showing this generic footer button there too would put two
          differently-worded upload buttons on screen at once. It only adds
          value for loading (about to resolve either way) and ready, where
          nothing else offers a way to add another sample. */}
      {state.tag !== "empty" && state.tag !== "error" && (
        <div>
          <Button
            type="button"
            variant="secondary"
            size="sm"
            disabled={disabled}
            onClick={() => setUploadOpen(true)}
          >
            {m.studio_tts_voice_sample_upload_btn()}
          </Button>
        </div>
      )}

      <VoiceSampleUploadModal
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        onCreated={handleCreated}
      />
    </fieldset>
  );
}


