/**
 * MediaToolSwitcher — the ".pswitch" Media-category pill nav from the Text
 * to Speech design board (Studio Tool Switchers board,
 * exploration/redesign-tool-switchers.html, region=media), rendered under
 * the page header (StudioContent's breadcrumb bar) and above the tool's own
 * cards. Scoped to the `text_to_speech` tool only — rendered by
 * `TextToSpeech.tsx` itself, NOT wired into shared Studio chrome
 * (StudioContent/StudioFormRenderer) for every tool: `StudioFormRenderer`
 * dispatches straight into this component's return with no intermediate
 * wrapper, so rendering this as the first child there is trivially already
 * tool-scoped, no shared-chrome change needed.
 *
 * Structurally mirrors the EXISTING `ProfileSwitcher.tsx`/`AnalysisSwitcher.tsx`
 * sibling components exactly (dot + icon + label pill, `<nav aria-label>`
 * landmark, trailing meta line) rather than inventing a new shape — this is
 * the same "*Switcher" family, just for the Media category.
 *
 * Per the canonical board markup, NONE of the 3 pills dim, badge, or
 * otherwise mark themselves "disabled" — every pill renders at FULL visual
 * weight regardless of whether its destination tool exists yet (confirmed
 * against the Content/Analysis/Visual switcher variants too: most of THEIR
 * listed tools don't exist as real tools in this app either, and none of
 * them get special disabled treatment). The board's own selection-cue rule
 * is the only variation:
 *   - EVERY pill's small decorative dot is ALWAYS colored with its own hue,
 *     active or not.
 *   - The icon and label take the hue color ONLY on the active pill (today:
 *     "Text to Speech", via the SAME `isImplementedNodeType()` gate the
 *     landing page and sidebar already use, so this stays correct without a
 *     manual edit here if Audio/Video to Text ever ship). Every inactive
 *     pill's icon+label render in plain neutral secondary text.
 * So exactly one colored icon is visible in the bar at a time.
 *
 * Derives its 3 pills from the EXISTING Studio task catalog
 * (`resolveStudioTasks()` filtered to `category === "media"`) rather than
 * hardcoding "Text to Speech"/"Audio to Text"/"Video to Text" — already-
 * canonical, already-11-locale-translated task names (`studioTasks.ts`'s
 * `TASK_MESSAGES`) and icons (`studioTaskIcons.ts`'s `iconForTask` — the
 * SAME sidebar-glyph SVGs used elsewhere: Volume2/AudioLines/Video).
 *
 * None of the 3 pills are real controls (no `<button>`, no `<a>`, no
 * `onClick`, no `tabIndex`) — "Text to Speech" has nowhere else to navigate
 * to (it IS the current page) and the other two have nowhere to navigate to
 * at all, so making any of them look focusable/clickable would be a false
 * affordance. This matches the canonical markup too: `data-goto` is a plain
 * data attribute in the static board demo, never a real click handler.
 *
 * Hues: Text to Speech = teal (this redesign's existing accent decision,
 * see TextToSpeech.tsx's module doc), Audio to Text = sky (a NEW,
 * single-purpose decorative ramp added to the shared preset — see
 * tailwind.preset.ts's own comment: explicitly NOT a 4th vertical accent,
 * mirrors cog-orange's severity-signaling carve-out), Video to Text =
 * violet (the EXISTING tertiary accent ramp, already used elsewhere for
 * Brand Profile/Propaganda Analysis — a new USE of it here, not a new
 * ramp).
 *
 * cog-* tokens only. RTL-safe logical properties (ms-auto, not ml-auto).
 */

import { type JSX } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { cn } from "@omnicore-platform/ui";
import type { LucideIcon } from "@omnicore-platform/ui/icons";
import { resolveStudioTasks } from "../../config/studioTasks";
import { iconForTask } from "../../config/studioTaskIcons";
import { isImplementedNodeType } from "../../lib/studioImplemented";

// ─── Per-task hue classes (dot always-on; text/icon color active-only) ──────

interface MediaHue {
  readonly dotClassName: string;
  readonly activeTextClassName: string;
}

const MEDIA_HUE_CLASSES: Readonly<Record<string, MediaHue>> = {
  "text-to-speech": {
    dotClassName: "bg-cog-teal-600 dark:bg-cog-teal-300",
    activeTextClassName: "text-cog-teal-700 dark:text-cog-teal-300",
  },
  "audio-to-text": {
    dotClassName: "bg-cog-sky-600 dark:bg-cog-sky-300",
    activeTextClassName: "text-cog-sky-700 dark:text-cog-sky-300",
  },
  "video-to-text": {
    dotClassName: "bg-cog-violet-600 dark:bg-cog-violet-dark-fg",
    activeTextClassName: "text-cog-violet-700 dark:text-cog-violet-dark-fg",
  },
};

export function MediaToolSwitcher(): JSX.Element {
  // resolveStudioTasks() is documented as "safe to call on every render —
  // synchronous and cheap" (studioTasks.ts) — matches StudioPage.tsx's own
  // precedent of calling it fresh rather than caching it module-scope (a
  // module-scope call would freeze the pill labels at whatever locale was
  // active the first time this module was imported, never reacting to a
  // later setLocale()).
  const mediaTasks = resolveStudioTasks().filter((task) => task.category === "media");

  return (
    <nav
      aria-label={m.studio_tts_media_switcher_label()}
      className="flex flex-wrap items-center gap-cog-2"
    >
      <div className="inline-flex flex-wrap gap-cog-1 rounded-lg border border-cog-border bg-cog-surface-muted p-cog-1">
        {mediaTasks.map((task) => {
          const isActive = isImplementedNodeType(task.nodeType);
          const hue = MEDIA_HUE_CLASSES[task.id];
          const Icon: LucideIcon = iconForTask(task.id);

          return (
            <span
              key={task.id}
              aria-current={isActive ? "true" : undefined}
              className={cn(
                "inline-flex items-center gap-cog-2 rounded-md px-cog-3 py-cog-1-5 text-body-sm font-semibold transition-colors",
                isActive
                  ? cn("bg-cog-surface shadow-cog-e1", hue.activeTextClassName)
                  : "text-cog-text-secondary",
              )}
            >
              <span
                aria-hidden="true"
                className={cn("h-cog-2 w-cog-2 shrink-0 rounded-pill", hue.dotClassName)}
              />
              <Icon aria-hidden="true" className="h-cog-4 w-cog-4 shrink-0" />
              {task.name}
            </span>
          );
        })}
      </div>

      <span className="ms-auto text-body-xs text-cog-text-tertiary">
        {/* Each text run wrapped in its own element (rather than two bare
            adjacent text nodes) so `screen.getByText()` can target either
            one exactly — RTL's default text matcher compares an element's
            own textContent, which only equals a single run when each run
            has its own node. */}
        <span>{m.studio_tts_media_switcher_meta()}</span>{" "}
        <b className="font-semibold text-cog-text-secondary">
          {m.studio_tts_media_switcher_count({ count: mediaTasks.length })}
        </b>
      </span>
    </nav>
  );
}


--- frontends/studio-mfe/src/tools/text-to-speech/TextToSpeechOutput.tsx (804 lines) ---
/**
 * TextToSpeechOutput — the real "ready" player for the Text to Speech tool
 * (#1069/#1070, Epic #1064), visually redesigned per the studio TTS
 * design-board export (Section 03 — see `TextToSpeech.tsx`'s own module doc
 * for the full redesign scope, including the layout/animation host side).
 *
 * Retains the pre-redesign data contract verbatim (`parseTtsOutputData`'s
 * shape, the waveform formula, the seek/play-pause/download wiring) and adds:
 *  - `format` on `TtsOutputData` (from `output.json.format`, BFF-computed
 *    from mimeType, defaults to "wav") — feeds the new header summary line.
 *  - Optional `onClose`/`onRegenerate` props — the host (`TextToSpeech.tsx`)
 *    always supplies both in real use; they're optional so this component's
 *    own bare unit-render call sites that don't exercise them don't need to
 *    thread through no-op callbacks.
 *  - A playback-speed control (1.0×→1.25×→1.5×→0.75×→1.0×, client-only,
 *    sets `audioRef.current.playbackRate`) — distinct from the metadata
 *    grid's fixed "Speed" fact (always "1.0×": the backend has no variable
 *    GENERATION speed; this control adjusts PLAYBACK only).
 *  - A script-readback clamp/expand toggle, and a 2-column 6-fact metadata
 *    grid (Duration/Words/Characters/Speed/Voice/Model) replacing the old
 *    5-pair `<dl>` (the raw script text moved into the readback block).
 *  - TTS's accent is teal (`cog-teal-*`), matching Voice Profile's
 *    established teal accent for voice-adjacent Studio tools, restyled from
 *    the pre-redesign blue.
 */

import {
  type ChangeEvent,
  type JSX,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocaleDirection } from "@omnicore-platform/platform-chrome";
import { Button, Slider, cn } from "@omnicore-platform/ui";
import { AudioLines, Download, Pause, Play, RotateCcw, X } from "@omnicore-platform/ui/icons";
import { isObject } from "../../lib/downloadGuards";
import { triggerDownload } from "../../lib/downloadFormats";
import { textToSpeechHandler } from "../../lib/downloadHandlers";
import { trimWav } from "../../lib/trimWav";
import { useToast } from "@omnicore-platform/ui/toast";
import type { StudioExecutionResult, StudioNodeOutput } from "../../types/output";

/** Minimum gap enforced between the two trim handles, in seconds — keeps a
 *  drag or arrow-key nudge from collapsing the kept region to zero. */
const MIN_TRIM_GAP_SECONDS = 0.5;

/** Arrow-key adjustment step for the trim handles, in seconds. */
const TRIM_KEY_STEP_SECONDS = 0.5;

/**
 * Value granularity the trim `Slider` reports, in seconds. Deliberately FINER
 * than TRIM_KEY_STEP_SECONDS: this is the resolution a pointer drag can land
 * on (the drag is computed continuously from the waveform's own rect below,
 * so the step never quantises it), NOT the keyboard nudge — the arrow/Home/End
 * semantics stay on this component's own handlers, which move by
 * TRIM_KEY_STEP_SECONDS.
 */
const TRIM_SLIDER_STEP_SECONDS = 0.1;

/**
 * MIN_TRIM_GAP_SECONDS expressed in `Slider` steps (0.5s / 0.1s = 5), which is
 * the unit Radix's `minStepsBetweenThumbs` counts in. `clampTrimStart` /
 * `clampTrimEnd` remain the enforcing path for this component's own keyboard
 * and pointer handling; this declares the same invariant to the primitive.
 */
const MIN_TRIM_GAP_STEPS = Math.round(MIN_TRIM_GAP_SECONDS / TRIM_SLIDER_STEP_SECONDS);

/**
 * Slack used when testing whether playback has reached the trimmed end.
 * `HTMLMediaElement.currentTime` snaps to the nearest representable sample, so
 * a seek to exactly `trimEnd` can settle marginally below it — an exact
 * comparison then fails to recognise "we are at the end". Kept far below
 * MIN_TRIM_GAP_SECONDS so it can never swallow a whole kept range.
 */
const PLAYBACK_BOUNDARY_EPSILON_SECONDS = 0.05;

function base64ToBytes(base64: string): Uint8Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

// ─── Waveform (decorative, deterministic — see module doc) ────────────────────

export const WAVEFORM_BAR_COUNT = 40;

export const WAVEFORM_BAR_HEIGHTS: readonly number[] = Array.from(
  { length: WAVEFORM_BAR_COUNT },
  (_, i) => {
    const h = Math.abs(Math.sin(i * 0.7) * 0.4 + Math.sin(i * 1.3) * 0.3 + 0.3) * 70 + 15;
    return Math.min(Math.max(h, 15), 85);
  },
);

// ─── Data parsing ─────────────────────────────────────────────────────────────

export interface TtsOutputData {
  readonly text: string;
  readonly voice: string;
  readonly model: string;
  readonly duration: number;
  readonly wordCount: number;
  readonly audioSrc: string;
  /** Lowercase container format string (e.g. "wav") — BFF-computed from
   *  mimeType, defaults to "wav". Rendered uppercased in the summary line. */
  readonly format: string;
}

export function parseTtsOutputData(output: StudioNodeOutput | undefined): TtsOutputData | null {
  if (output === undefined) return null;

  const audio = output.binary?.audio;
  if (!isObject(audio)) return null;
  const data = audio["data"];
  if (typeof data !== "string" || data.length === 0) return null;

  const mimeType = typeof audio["mimeType"] === "string" ? audio["mimeType"] : "audio/wav";
  const json = isObject(output.json) ? output.json : {};

  return {
    text: typeof json["text"] === "string" ? json["text"] : "",
    voice: typeof json["voice"] === "string" ? json["voice"] : "",
    model: typeof json["model"] === "string" ? json["model"] : "",
    duration: typeof json["duration"] === "number" ? json["duration"] : 0,
    wordCount: typeof json["wordCount"] === "number" ? json["wordCount"] : 0,
    audioSrc: `data:${mimeType};base64,${data}`,
    format: typeof json["format"] === "string" && json["format"].length > 0 ? json["format"] : "wav",
  };
}

// ─── Time formatting ──────────────────────────────────────────────────────────

export function formatPlaybackTime(totalSeconds: number): string {
  const safe = Number.isFinite(totalSeconds) ? Math.max(0, Math.floor(totalSeconds)) : 0;
  const minutes = Math.floor(safe / 60);
  const seconds = safe % 60;
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

// ─── Playback speed (NEW — client-only, cycles a fixed step list) ───────────

interface SpeedStep {
  readonly label: string;
  readonly rate: number;
}

/** Cycle order per the design board: 1.0× → 1.25× → 1.5× → 0.75× → 1.0×. */
const SPEED_STEPS: readonly SpeedStep[] = [
  { label: "1.0", rate: 1 },
  { label: "1.25", rate: 1.25 },
  { label: "1.5", rate: 1.5 },
  { label: "0.75", rate: 0.75 },
];

// ─── Component ────────────────────────────────────────────────────────────────

const HEADING_ID = "tts-output-heading";

export interface TextToSpeechOutputProps {
  readonly output: StudioNodeOutput | undefined;
  /** Closes/discards the result back to the empty state (calls the host's
   *  `reset()` + optional `onDiscardOutput`). Omitted in bare unit-render
   *  call sites that don't exercise this — the button simply doesn't render. */
  readonly onClose?: () => void;
  /** Re-invokes generation with the last-submitted inputs. Omitted the same way. */
  readonly onRegenerate?: () => void;
}

export function TextToSpeechOutput({
  output,
  onClose,
  onRegenerate,
}: TextToSpeechOutputProps): JSX.Element {
  const data = parseTtsOutputData(output);
  const isRTL = useLocaleDirection() === "rtl";
  const audioRef = useRef<HTMLAudioElement>(null);
  const waveformRef = useRef<HTMLDivElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [loadedDuration, setLoadedDuration] = useState(0);
  const [speedIndex, setSpeedIndex] = useState(0);
  const [scriptExpanded, setScriptExpanded] = useState(false);
  const [trimStart, setTrimStart] = useState(0);
  // `null` means "not yet touched" — tracks the effective (possibly still
  // loading) duration automatically rather than freezing at whatever
  // duration was known at first render.
  const [trimEndOverride, setTrimEndOverride] = useState<number | null>(null);
  const [draggingHandle, setDraggingHandle] = useState<"start" | "end" | null>(null);
  const toast = useToast();

  const effectiveDuration = loadedDuration > 0 ? loadedDuration : (data?.duration ?? 0);
  const trimEnd = trimEndOverride ?? effectiveDuration;
  const isTrimModified = trimStart > 0 || trimEndOverride !== null;

  function clampTrimStart(next: number): number {
    return Math.min(Math.max(0, next), trimEnd - MIN_TRIM_GAP_SECONDS);
  }

  function clampTrimEnd(next: number): number {
    return Math.max(Math.min(effectiveDuration, next), trimStart + MIN_TRIM_GAP_SECONDS);
  }

  function percentFromClientX(clientX: number): number {
    const el = waveformRef.current;
    if (el === null) return 0;
    const rect = el.getBoundingClientRect();
    if (rect.width === 0) return 0;
    const ratio = (clientX - rect.left) / rect.width;
    const clamped = Math.min(1, Math.max(0, ratio));
    return isRTL ? 1 - clamped : clamped;
  }

  // Pointer-drag support for the two trim handles. Subscribes to window-level
  // pointermove/pointerup only while a drag is active, and always cleans up
  // (on drag end or unmount) — the required pattern for any subscription.
  useEffect(() => {
    if (draggingHandle === null) return undefined;

    function onMove(ev: PointerEvent): void {
      const seconds = percentFromClientX(ev.clientX) * effectiveDuration;
      if (draggingHandle === "start") {
        setTrimStart(clampTrimStart(seconds));
      } else {
        setTrimEndOverride(clampTrimEnd(seconds));
      }
    }
    function onUp(): void {
      setDraggingHandle(null);
    }

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draggingHandle, effectiveDuration, trimStart, trimEnd, isRTL]);

  if (data === null) {
    return (
      <div
        role="status"
        className="flex flex-1 items-center justify-center rounded-md border border-dashed border-cog-border bg-cog-surface-muted p-cog-4 text-body-sm text-cog-text-secondary"
      >
        {m.studio_tts_output_empty()}
      </div>
    );
  }

  const progressPercent = effectiveDuration > 0 ? (currentTime / effectiveDuration) * 100 : 0;

  function handlePlayPause(): void {
    const audio = audioRef.current;
    if (audio === null) return;
    if (isPlaying) {
      audio.pause();
    } else {
      // The end comparison needs PLAYBACK_BOUNDARY_EPSILON_SECONDS of slack:
      // HTMLMediaElement.currentTime seeks to the nearest representable
      // sample, so the `audio.currentTime = trimEnd` that handleTimeUpdate
      // performs when stopping can settle a hair BELOW trimEnd. An exact
      // `>= trimEnd` test is then false on the next play, so playback resumed
      // just short of the end and stopped again within one timeupdate tick —
      // which read as "play does nothing" while the end trim still worked.
      if (
        audio.currentTime < trimStart ||
        audio.currentTime >= trimEnd - PLAYBACK_BOUNDARY_EPSILON_SECONDS
      ) {
        audio.currentTime = trimStart;
        setCurrentTime(trimStart);
      }
      void audio.play();
    }
  }

  function handleTimeUpdate(): void {
    const audio = audioRef.current;
    if (audio === null) return;
    if (audio.currentTime >= trimEnd) {
      audio.pause();
      audio.currentTime = trimEnd;
      setCurrentTime(trimEnd);
      return;
    }
    setCurrentTime(audio.currentTime);
  }

  function handleLoadedMetadata(): void {
    const audio = audioRef.current;
    if (audio !== null && Number.isFinite(audio.duration)) {
      setLoadedDuration(audio.duration);
    }
  }

  function handleEnded(): void {
    setIsPlaying(false);
    setCurrentTime(trimStart);
    const audio = audioRef.current;
    if (audio !== null) audio.currentTime = trimStart;
  }

  function handleSeek(event: ChangeEvent<HTMLInputElement>): void {
    const raw = Number(event.target.value);
    const next = Math.min(trimEnd, Math.max(trimStart, raw));
    const audio = audioRef.current;
    if (audio !== null) audio.currentTime = next;
    setCurrentTime(next);
  }

  function handleCycleSpeed(): void {
    const nextIndex = (speedIndex + 1) % SPEED_STEPS.length;
    setSpeedIndex(nextIndex);
    const audio = audioRef.current;
    if (audio !== null) audio.playbackRate = SPEED_STEPS[nextIndex].rate;
  }

  function handleResetTrim(): void {
    setTrimStart(0);
    setTrimEndOverride(null);
  }

  function handleTrimStartKeyDown(event: KeyboardEvent<HTMLSpanElement>): void {
    let next: number | null = null;
    if (event.key === "ArrowRight" || event.key === "ArrowUp") {
      next = trimStart + TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
      next = trimStart - TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "Home") {
      next = 0;
    } else if (event.key === "End") {
      next = trimEnd - MIN_TRIM_GAP_SECONDS;
    }
    if (next === null) return;
    event.preventDefault();
    setTrimStart(clampTrimStart(next));
  }

  function handleTrimEndKeyDown(event: KeyboardEvent<HTMLSpanElement>): void {
    let next: number | null = null;
    if (event.key === "ArrowRight" || event.key === "ArrowUp") {
      next = trimEnd + TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
      next = trimEnd - TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "Home") {
      next = trimStart + MIN_TRIM_GAP_SECONDS;
    } else if (event.key === "End") {
      next = effectiveDuration;
    }
    if (next === null) return;
    event.preventDefault();
    setTrimEndOverride(clampTrimEnd(next));
  }

  /**
   * Which trim thumb an event landed on — 0 = start, 1 = end, -1 = neither
   * (the Slider's own rail). The two handles are thumbs of ONE `Slider`, so
   * their events surface on the shared Root and have to be routed by position
   * in the Root's own thumb order rather than by two separate listeners.
   */
  function trimThumbIndex(target: EventTarget | null, root: HTMLElement): number {
    if (!(target instanceof Element)) return -1;
    const thumb = target.closest('[role="slider"]');
    if (thumb === null) return -1;
    return Array.from(root.querySelectorAll('[role="slider"]')).indexOf(thumb);
  }

  function handleTrimKeyDown(event: KeyboardEvent<HTMLSpanElement>): void {
    const index = trimThumbIndex(event.target, event.currentTarget);
    if (index === 0) handleTrimStartKeyDown(event);
    else if (index === 1) handleTrimEndKeyDown(event);
  }

  function handleTrimPointerDown(event: ReactPointerEvent<HTMLSpanElement>): void {
    // Radix composes a caller's handler AHEAD of its own and skips its own
    // once the event is default-prevented, so this keeps the waveform-relative
    // (and RTL-mirrored) drag below authoritative and stops a click on the
    // rail from moving the nearest handle — neither of which the hand-rolled
    // handles did.
    event.preventDefault();
    const index = trimThumbIndex(event.target, event.currentTarget);
    if (index === 0) setDraggingHandle("start");
    else if (index === 1) setDraggingHandle("end");
  }

  async function handleDownload(): Promise<void> {
    try {
      if (isTrimModified) {
        const audio = output?.binary?.["audio"];
        if (!isObject(audio) || typeof audio["data"] !== "string" || audio["data"].length === 0) {
          throw new Error("No binary audio data available for download");
        }
        const mimeType = typeof audio["mimeType"] === "string" ? audio["mimeType"] : "audio/wav";
        const fileName = typeof audio["fileName"] === "string" ? audio["fileName"] : undefined;
        const bytes = base64ToBytes(audio["data"]);
        const trimmedBytes = trimWav(bytes, trimStart, trimEnd);
        const blob = new Blob([trimmedBytes.buffer as ArrayBuffer], { type: mimeType });
        const rawName = fileName ?? `speech-${Date.now()}`;
        const effectiveFilename = rawName.endsWith(".wav") ? rawName : `${rawName}.wav`;
        triggerDownload(blob, effectiveFilename);
        toast.success(m.studio_tts_output_download_success());
        return;
      }
      const result: StudioExecutionResult = { success: true, output };
      await textToSpeechHandler({ result, format: "wav" });
      toast.success(m.studio_tts_output_download_success());
    } catch {
      toast.error(m.studio_tts_output_download_failed());
    }
  }

  const bars = WAVEFORM_BAR_HEIGHTS.map((height, index) => ({
    index,
    height,
    isActive: progressPercent > (index / WAVEFORM_BAR_COUNT) * 100,
  }));
  const orderedBars = isRTL ? [...bars].reverse() : bars;

  const trimStartPercent = effectiveDuration > 0 ? (trimStart / effectiveDuration) * 100 : 0;
  const trimEndPercent = effectiveDuration > 0 ? (trimEnd / effectiveDuration) * 100 : 100;

  const speedLabel = SPEED_STEPS[speedIndex].label;
  const speedValueText = m.studio_tts_player_speed_value({ speed: speedLabel });
  const summaryText = m.studio_tts_output_summary({
    time: formatPlaybackTime(effectiveDuration),
    format: data.format.toUpperCase(),
    model: data.model,
  });

  return (
    <div
      role="region"
      aria-labelledby={HEADING_ID}
      className="flex w-full flex-col gap-cog-4 rounded-xl border border-cog-border bg-cog-surface p-cog-5 shadow-cog-e2"
    >
      <div className="flex items-start justify-between gap-cog-3">
        <div className="flex items-start gap-cog-3">
          <span
            aria-hidden="true"
            className="flex h-cog-6-5 w-cog-6-5 shrink-0 items-center justify-center rounded-lg bg-cog-teal-50 text-cog-teal-700 dark:bg-cog-teal-900/20 dark:text-cog-teal-300"
          >
            <AudioLines aria-hidden="true" className="h-cog-4 w-cog-4" />
          </span>
          <div className="flex flex-col gap-cog-0-5">
            <h2 id={HEADING_ID} className="text-heading-sm text-cog-text-primary">
              {m.studio_tts_output_ready_heading()}
            </h2>
            <p className="text-body-sm text-cog-text-tertiary">{summaryText}</p>
          </div>
        </div>

        {onClose && (
          <button
            type="button"
            aria-label={m.studio_tts_output_close_action()}
            onClick={onClose}
            className={cn(
              "flex h-cog-6 w-cog-6 shrink-0 items-center justify-center rounded-md text-cog-text-tertiary",
              "hover:bg-cog-surface-muted hover:text-cog-text-primary",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus",
            )}
          >
            <X aria-hidden="true" className="h-cog-4 w-cog-4" />
          </button>
        )}
      </div>

      {/* eslint-disable-next-line jsx-a11y/media-has-caption -- no caption track: the synthesized source text (`data.text`) is rendered as a full transcript in the "Script readback" block below, always visible/expandable, adjacent to this player. */}
      <audio
        ref={audioRef}
        data-testid="tts-audio-player"
        src={data.audioSrc}
        onPlay={() => setIsPlaying(true)}
        onPause={() => setIsPlaying(false)}
        onEnded={handleEnded}
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleLoadedMetadata}
      />

      {/* Waveform — decorative only; the seek bar + counters below carry the
          real accessible progress information. The trim handles overlaid on
          top ARE accessible (role="slider", keyboard-operable) — they carry
          their own aria-label/aria-valuetext independent of the waveform's
          own aria-hidden.

          Section 09 "Grab handles + hatched offcuts" (Option A): a tinted
          kept-region band sits behind the bars, the offcuts are hatched
          instead of merely dimmed, wide grab handles carry two grip lines
          each, and a time bubble rides above each handle. `pt-cog-7-5` (44px)
          reserves room for the bubbles so they don't clip against whatever
          sits above the waveform. */}
      <div ref={waveformRef} data-testid="tts-waveform" className="relative pt-cog-7-5">
        {/* Kept-region band (z-0) — renders BEHIND the bars (z-1). */}
        <div
          aria-hidden="true"
          data-testid="tts-trim-band"
          style={{
            insetInlineStart: `${trimStartPercent}%`,
            width: `${trimEndPercent - trimStartPercent}%`,
          }}
          className="pointer-events-none absolute -top-cog-2 -bottom-cog-2 z-0 rounded-md border-y-2 border-cog-teal-600 bg-cog-teal-600/[.12] dark:bg-cog-teal-500/[.15]"
        />

        <div className="relative z-cog-stack-1 flex h-cog-9 items-end gap-cog-0-5" aria-hidden="true">
          {orderedBars.map((bar) => (
            <div
              key={bar.index}
              data-bar-index={bar.index}
              style={{ height: `${bar.height}%` }}
              className={cn(
                "flex-1 rounded-pill transition-colors duration-standard",
                // Unplayed bars are cog-border, not cog-surface-muted: muted
                // lands within ~5% of the card's own cog-surface in light mode
                // (242,240,236 on 255,255,255) and only just above it in dark
                // (34,37,46 on 19,21,26), so a freshly generated clip's
                // waveform was nearly invisible until you played it. One token
                // fixes both modes in the right direction — cog-border is
                // darker than the surface in light (210,218,228) and lighter in
                // dark (71,85,105).
                bar.isActive ? "bg-cog-teal-600" : "bg-cog-border",
                isPlaying && "animate-pulse",
              )}
            />
          ))}
        </div>

        {/* Trimmed-away (offcut) regions render hatched so the kept region
            is visually obvious, independent of the handle positions below.
            The repeating-linear-gradient hatch can't be expressed as a
            cog-* class, so it's the one documented inline-style exception —
            it reads `--cog-text-secondary` (the same CSS variable
            `text-cog-text-secondary` resolves to) rather than a raw hex. */}
        <div
          aria-hidden="true"
          data-testid="tts-trim-dim-start"
          style={{
            insetInlineStart: 0,
            width: `${trimStartPercent}%`,
            backgroundImage:
              "repeating-linear-gradient(45deg, transparent, transparent 4.5px, rgb(var(--cog-text-secondary)) 4.5px, rgb(var(--cog-text-secondary)) 6px)",
          }}
          className="pointer-events-none absolute -top-cog-2 -bottom-cog-2 z-0 rounded-md opacity-70"
        />
        <div
          aria-hidden="true"
          data-testid="tts-trim-dim-end"
          style={{
            insetInlineEnd: 0,
            width: `${100 - trimEndPercent}%`,
            backgroundImage:
              "repeating-linear-gradient(45deg, transparent, transparent 4.5px, rgb(var(--cog-text-secondary)) 4.5px, rgb(var(--cog-text-secondary)) 6px)",
          }}
          className="pointer-events-none absolute -top-cog-2 -bottom-cog-2 z-0 rounded-md opacity-70"
        />

        {/* Section 09's two grab handles are ONE range `Slider`, not two
            widgets: a single Radix Root with a thumb per value, so the start
            and end share one control (and one min-gap invariant) while each
            thumb keeps its own accessible name and mm:ss `aria-valuetext`.

            The Root overlays the waveform with its stock rail and fill
            suppressed (`classNames.track` transparent, `classNames.range`
            hidden) — the tinted kept-region band and the hatched offcuts
            above already draw that region — and `renderThumb` supplies
            Section 09's art: a full-height teal bar with two grip lines, and
            the time bubble riding above it. The bubble lives INSIDE the thumb
            so it tracks the handle's own painted position.

            `h-cog-25` (124px) is the Root's own height, spelled out because a
            Radix thumb's wrapper shrink-wraps its content and so cannot
            inherit it: pt-cog-7-5 (44) + the bars' h-cog-9 (64) + the
            -top-cog-2/-bottom-cog-2 overhang (2x8) = 124.

            Keyboard and pointer handling stay on this component (see
            `handleTrimPointerDown`) — `step` only sets the granularity the
            primitive reports, never the 0.5s arrow/Home/End nudge. */}
        <Slider
          value={[trimStart, trimEnd]}
          min={0}
          max={effectiveDuration}
          step={TRIM_SLIDER_STEP_SECONDS}
          minStepsBetweenThumbs={MIN_TRIM_GAP_STEPS}
          dir={isRTL ? "rtl" : "ltr"}
          thumbLabels={[m.studio_tts_trim_start_label(), m.studio_tts_trim_end_label()]}
          ariaValueText={[formatPlaybackTime(trimStart), formatPlaybackTime(trimEnd)]}
          onKeyDown={handleTrimKeyDown}
          onPointerDown={handleTrimPointerDown}
          className="absolute inset-x-cog-0 -top-cog-2 -bottom-cog-2 z-cog-stack-3"
          classNames={{
            track: "h-full rounded-none bg-transparent",
            range: "hidden",
            thumb: "h-cog-25 cursor-ew-resize",
          }}
          renderThumb={(index) => (
            <>
              <span
                aria-hidden="true"
                data-testid={index === 0 ? "tts-trim-start-bubble" : "tts-trim-end-bubble"}
                className="absolute -top-cog-5 left-1/2 z-cog-stack-4 flex h-cog-4-5 -translate-x-1/2 items-center whitespace-nowrap rounded-base bg-cog-teal-600 px-cog-2 text-micro font-bold tabular-nums text-white dark:text-cog-canvas"
