          {m.studio_tts_trim_reset_action()}
        </button>
      </div>

      {/* Controls: current time / play-pause / seek bar / total duration / speed */}
      <div className="flex items-center gap-cog-3">
        <span
          data-testid="tts-current-time"
          className="w-cog-7 shrink-0 text-end text-body-sm tabular-nums text-cog-text-secondary"
