            "flex h-cog-7-5 w-cog-7-5 shrink-0 items-center justify-center rounded-pill",
            "bg-cog-teal-600 text-white",
            "transition-[transform,box-shadow] duration-standard",
            "hover:-translate-y-px hover:shadow-cog-glow-teal dark:hover:shadow-cog-glow-teal-dark",
