          {formatPlaybackTime(effectiveDuration)}
        </span>

        {/* Playback-speed control (NEW) — client-only, cycles the audio
            element's own playbackRate. Distinct from the metadata card's
            fixed "Speed" (generation-time) fact below. */}
        <button
          type="button"
          onClick={handleCycleSpeed}
          aria-label={m.studio_tts_player_speed_action({ speed: speedValueText })}
          className={cn(
