/**
 * TextToSpeechOutput — the real "ready" player for the Text to Speech tool
 * (#1069/#1070, Epic #1064), visually redesigned per the studio TTS
 * design-board export (Section 03 — see `TextToSpeech.tsx`'s own module doc
 * for the full redesign scope, including the layout/animation host side).
 *
 * Retains the pre-redesign data contract verbatim (`parseTtsOutputData`'s
 * shape, the waveform formula, the seek/play-pause/download wiring) and adds:
 *  - `format` on `TtsOutputData` (from `output.json.format`, BFF-computed
 *    from mimeType, defaults to "wav") — feeds the new header summary line.
 *  - Optional `onClose`/`onRegenerate` props — the host (`TextToSpeech.tsx`)
 *    always supplies both in real use; they're optional so this component's
 *    own bare unit-render call sites that don't exercise them don't need to
 *    thread through no-op callbacks.
 *  - A playback-speed control (1.0×→1.25×→1.5×→0.75×→1.0×, client-only,
 *    sets `audioRef.current.playbackRate`) — distinct from the metadata
 *    grid's fixed "Speed" fact (always "1.0×": the backend has no variable
 *    GENERATION speed; this control adjusts PLAYBACK only).
 *  - A script-readback clamp/expand toggle, and a 2-column 6-fact metadata
 *    grid (Duration/Words/Characters/Speed/Voice/Model) replacing the old
 *    5-pair `<dl>` (the raw script text moved into the readback block).
 *  - TTS's accent is teal (`cog-teal-*`), matching Voice Profile's
 *    established teal accent for voice-adjacent Studio tools, restyled from
 *    the pre-redesign blue.
 */

import {
  type ChangeEvent,
  type JSX,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocaleDirection } from "@omnicore-platform/platform-chrome";
import { Button, Slider, cn } from "@omnicore-platform/ui";
import { AudioLines, Download, Pause, Play, RotateCcw, X } from "@omnicore-platform/ui/icons";
import { isObject } from "../../lib/downloadGuards";
import { triggerDownload } from "../../lib/downloadFormats";
import { textToSpeechHandler } from "../../lib/downloadHandlers";
import { trimWav } from "../../lib/trimWav";
import { useToast } from "@omnicore-platform/ui/toast";
import type { StudioExecutionResult, StudioNodeOutput } from "../../types/output";

/** Minimum gap enforced between the two trim handles, in seconds — keeps a
 *  drag or arrow-key nudge from collapsing the kept region to zero. */
const MIN_TRIM_GAP_SECONDS = 0.5;

/** Arrow-key adjustment step for the trim handles, in seconds. */
const TRIM_KEY_STEP_SECONDS = 0.5;

/**
 * Value granularity the trim `Slider` reports, in seconds. Deliberately FINER
 * than TRIM_KEY_STEP_SECONDS: this is the resolution a pointer drag can land
 * on (the drag is computed continuously from the waveform's own rect below,
 * so the step never quantises it), NOT the keyboard nudge — the arrow/Home/End
 * semantics stay on this component's own handlers, which move by
 * TRIM_KEY_STEP_SECONDS.
 */
const TRIM_SLIDER_STEP_SECONDS = 0.1;

/**
 * MIN_TRIM_GAP_SECONDS expressed in `Slider` steps (0.5s / 0.1s = 5), which is
 * the unit Radix's `minStepsBetweenThumbs` counts in. `clampTrimStart` /
 * `clampTrimEnd` remain the enforcing path for this component's own keyboard
 * and pointer handling; this declares the same invariant to the primitive.
 */
const MIN_TRIM_GAP_STEPS = Math.round(MIN_TRIM_GAP_SECONDS / TRIM_SLIDER_STEP_SECONDS);

/**
 * Slack used when testing whether playback has reached the trimmed end.
 * `HTMLMediaElement.currentTime` snaps to the nearest representable sample, so
 * a seek to exactly `trimEnd` can settle marginally below it — an exact
 * comparison then fails to recognise "we are at the end". Kept far below
 * MIN_TRIM_GAP_SECONDS so it can never swallow a whole kept range.
 */
const PLAYBACK_BOUNDARY_EPSILON_SECONDS = 0.05;

function base64ToBytes(base64: string): Uint8Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

// ─── Waveform (decorative, deterministic — see module doc) ────────────────────

export const WAVEFORM_BAR_COUNT = 40;

export const WAVEFORM_BAR_HEIGHTS: readonly number[] = Array.from(
  { length: WAVEFORM_BAR_COUNT },
  (_, i) => {
    const h = Math.abs(Math.sin(i * 0.7) * 0.4 + Math.sin(i * 1.3) * 0.3 + 0.3) * 70 + 15;
    return Math.min(Math.max(h, 15), 85);
  },
);

// ─── Data parsing ─────────────────────────────────────────────────────────────

export interface TtsOutputData {
  readonly text: string;
  readonly voice: string;
  readonly model: string;
  readonly duration: number;
  readonly wordCount: number;
  readonly audioSrc: string;
  /** Lowercase container format string (e.g. "wav") — BFF-computed from
   *  mimeType, defaults to "wav". Rendered uppercased in the summary line. */
  readonly format: string;
}

export function parseTtsOutputData(output: StudioNodeOutput | undefined): TtsOutputData | null {
  if (output === undefined) return null;

  const audio = output.binary?.audio;
  if (!isObject(audio)) return null;
  const data = audio["data"];
  if (typeof data !== "string" || data.length === 0) return null;

  const mimeType = typeof audio["mimeType"] === "string" ? audio["mimeType"] : "audio/wav";
  const json = isObject(output.json) ? output.json : {};

  return {
    text: typeof json["text"] === "string" ? json["text"] : "",
    voice: typeof json["voice"] === "string" ? json["voice"] : "",
    model: typeof json["model"] === "string" ? json["model"] : "",
    duration: typeof json["duration"] === "number" ? json["duration"] : 0,
    wordCount: typeof json["wordCount"] === "number" ? json["wordCount"] : 0,
    audioSrc: `data:${mimeType};base64,${data}`,
    format: typeof json["format"] === "string" && json["format"].length > 0 ? json["format"] : "wav",
  };
}

// ─── Time formatting ──────────────────────────────────────────────────────────

export function formatPlaybackTime(totalSeconds: number): string {
  const safe = Number.isFinite(totalSeconds) ? Math.max(0, Math.floor(totalSeconds)) : 0;
  const minutes = Math.floor(safe / 60);
  const seconds = safe % 60;
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

// ─── Playback speed (NEW — client-only, cycles a fixed step list) ───────────

interface SpeedStep {
  readonly label: string;
  readonly rate: number;
}

/** Cycle order per the design board: 1.0× → 1.25× → 1.5× → 0.75× → 1.0×. */
const SPEED_STEPS: readonly SpeedStep[] = [
  { label: "1.0", rate: 1 },
  { label: "1.25", rate: 1.25 },
  { label: "1.5", rate: 1.5 },
  { label: "0.75", rate: 0.75 },
];

// ─── Component ────────────────────────────────────────────────────────────────

const HEADING_ID = "tts-output-heading";

export interface TextToSpeechOutputProps {
  readonly output: StudioNodeOutput | undefined;
  /** Closes/discards the result back to the empty state (calls the host's
   *  `reset()` + optional `onDiscardOutput`). Omitted in bare unit-render
   *  call sites that don't exercise this — the button simply doesn't render. */
  readonly onClose?: () => void;
  /** Re-invokes generation with the last-submitted inputs. Omitted the same way. */
  readonly onRegenerate?: () => void;
}

export function TextToSpeechOutput({
  output,
  onClose,
  onRegenerate,
}: TextToSpeechOutputProps): JSX.Element {
  const data = parseTtsOutputData(output);
  const isRTL = useLocaleDirection() === "rtl";
  const audioRef = useRef<HTMLAudioElement>(null);
  const waveformRef = useRef<HTMLDivElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [loadedDuration, setLoadedDuration] = useState(0);
  const [speedIndex, setSpeedIndex] = useState(0);
  const [scriptExpanded, setScriptExpanded] = useState(false);
  const [trimStart, setTrimStart] = useState(0);
  // `null` means "not yet touched" — tracks the effective (possibly still
  // loading) duration automatically rather than freezing at whatever
  // duration was known at first render.
  const [trimEndOverride, setTrimEndOverride] = useState<number | null>(null);
  const [draggingHandle, setDraggingHandle] = useState<"start" | "end" | null>(null);
  const toast = useToast();

  const effectiveDuration = loadedDuration > 0 ? loadedDuration : (data?.duration ?? 0);
  const trimEnd = trimEndOverride ?? effectiveDuration;
  const isTrimModified = trimStart > 0 || trimEndOverride !== null;

  function clampTrimStart(next: number): number {
    return Math.min(Math.max(0, next), trimEnd - MIN_TRIM_GAP_SECONDS);
  }

  function clampTrimEnd(next: number): number {
    return Math.max(Math.min(effectiveDuration, next), trimStart + MIN_TRIM_GAP_SECONDS);
  }

  function percentFromClientX(clientX: number): number {
    const el = waveformRef.current;
    if (el === null) return 0;
    const rect = el.getBoundingClientRect();
    if (rect.width === 0) return 0;
    const ratio = (clientX - rect.left) / rect.width;
    const clamped = Math.min(1, Math.max(0, ratio));
    return isRTL ? 1 - clamped : clamped;
  }

  // Pointer-drag support for the two trim handles. Subscribes to window-level
  // pointermove/pointerup only while a drag is active, and always cleans up
  // (on drag end or unmount) — the required pattern for any subscription.
  useEffect(() => {
    if (draggingHandle === null) return undefined;

    function onMove(ev: PointerEvent): void {
      const seconds = percentFromClientX(ev.clientX) * effectiveDuration;
      if (draggingHandle === "start") {
        setTrimStart(clampTrimStart(seconds));
      } else {
        setTrimEndOverride(clampTrimEnd(seconds));
      }
    }
    function onUp(): void {
      setDraggingHandle(null);
    }

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draggingHandle, effectiveDuration, trimStart, trimEnd, isRTL]);

  if (data === null) {
    return (
      <div
        role="status"
        className="flex flex-1 items-center justify-center rounded-md border border-dashed border-cog-border bg-cog-surface-muted p-cog-4 text-body-sm text-cog-text-secondary"
      >
        {m.studio_tts_output_empty()}
      </div>
    );
  }

  const progressPercent = effectiveDuration > 0 ? (currentTime / effectiveDuration) * 100 : 0;

  function handlePlayPause(): void {
    const audio = audioRef.current;
    if (audio === null) return;
    if (isPlaying) {
      audio.pause();
    } else {
      // The end comparison needs PLAYBACK_BOUNDARY_EPSILON_SECONDS of slack:
      // HTMLMediaElement.currentTime seeks to the nearest representable
      // sample, so the `audio.currentTime = trimEnd` that handleTimeUpdate
      // performs when stopping can settle a hair BELOW trimEnd. An exact
      // `>= trimEnd` test is then false on the next play, so playback resumed
      // just short of the end and stopped again within one timeupdate tick —
      // which read as "play does nothing" while the end trim still worked.
      if (
        audio.currentTime < trimStart ||
        audio.currentTime >= trimEnd - PLAYBACK_BOUNDARY_EPSILON_SECONDS
      ) {
        audio.currentTime = trimStart;
        setCurrentTime(trimStart);
      }
      void audio.play();
    }
  }

  function handleTimeUpdate(): void {
    const audio = audioRef.current;
    if (audio === null) return;
    if (audio.currentTime >= trimEnd) {
      audio.pause();
      audio.currentTime = trimEnd;
      setCurrentTime(trimEnd);
      return;
    }
    setCurrentTime(audio.currentTime);
  }

  function handleLoadedMetadata(): void {
    const audio = audioRef.current;
    if (audio !== null && Number.isFinite(audio.duration)) {
      setLoadedDuration(audio.duration);
    }
  }

  function handleEnded(): void {
    setIsPlaying(false);
    setCurrentTime(trimStart);
    const audio = audioRef.current;
    if (audio !== null) audio.currentTime = trimStart;
  }

  function handleSeek(event: ChangeEvent<HTMLInputElement>): void {
    const raw = Number(event.target.value);
    const next = Math.min(trimEnd, Math.max(trimStart, raw));
    const audio = audioRef.current;
    if (audio !== null) audio.currentTime = next;
    setCurrentTime(next);
  }

  function handleCycleSpeed(): void {
    const nextIndex = (speedIndex + 1) % SPEED_STEPS.length;
    setSpeedIndex(nextIndex);
    const audio = audioRef.current;
    if (audio !== null) audio.playbackRate = SPEED_STEPS[nextIndex].rate;
  }

  function handleResetTrim(): void {
    setTrimStart(0);
    setTrimEndOverride(null);
  }

  function handleTrimStartKeyDown(event: KeyboardEvent<HTMLSpanElement>): void {
    let next: number | null = null;
    if (event.key === "ArrowRight" || event.key === "ArrowUp") {
      next = trimStart + TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
      next = trimStart - TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "Home") {
      next = 0;
    } else if (event.key === "End") {
      next = trimEnd - MIN_TRIM_GAP_SECONDS;
    }
    if (next === null) return;
    event.preventDefault();
    setTrimStart(clampTrimStart(next));
  }

  function handleTrimEndKeyDown(event: KeyboardEvent<HTMLSpanElement>): void {
    let next: number | null = null;
    if (event.key === "ArrowRight" || event.key === "ArrowUp") {
      next = trimEnd + TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
      next = trimEnd - TRIM_KEY_STEP_SECONDS;
    } else if (event.key === "Home") {
      next = trimStart + MIN_TRIM_GAP_SECONDS;
    } else if (event.key === "End") {
      next = effectiveDuration;
    }
    if (next === null) return;
    event.preventDefault();
    setTrimEndOverride(clampTrimEnd(next));
  }

  /**
   * Which trim thumb an event landed on — 0 = start, 1 = end, -1 = neither
   * (the Slider's own rail). The two handles are thumbs of ONE `Slider`, so
   * their events surface on the shared Root and have to be routed by position
   * in the Root's own thumb order rather than by two separate listeners.
   */
  function trimThumbIndex(target: EventTarget | null, root: HTMLElement): number {
    if (!(target instanceof Element)) return -1;
    const thumb = target.closest('[role="slider"]');
    if (thumb === null) return -1;
    return Array.from(root.querySelectorAll('[role="slider"]')).indexOf(thumb);
  }

  function handleTrimKeyDown(event: KeyboardEvent<HTMLSpanElement>): void {
    const index = trimThumbIndex(event.target, event.currentTarget);
    if (index === 0) handleTrimStartKeyDown(event);
    else if (index === 1) handleTrimEndKeyDown(event);
  }

