    // Radix composes a caller's handler AHEAD of its own and skips its own
    // once the event is default-prevented, so this keeps the waveform-relative
    // (and RTL-mirrored) drag below authoritative and stops a click on the
    // rail from moving the nearest handle — neither of which the hand-rolled
    // handles did.
    event.preventDefault();
    const index = trimThumbIndex(event.target, event.currentTarget);
    if (index === 0) setDraggingHandle("start");
    else if (index === 1) setDraggingHandle("end");
  }

  async function handleDownload(): Promise<void> {
    try {
      if (isTrimModified) {
        const audio = output?.binary?.["audio"];
        if (!isObject(audio) || typeof audio["data"] !== "string" || audio["data"].length === 0) {
          throw new Error("No binary audio data available for download");
        }
        const mimeType = typeof audio["mimeType"] === "string" ? audio["mimeType"] : "audio/wav";
        const fileName = typeof audio["fileName"] === "string" ? audio["fileName"] : undefined;
        const bytes = base64ToBytes(audio["data"]);
        const trimmedBytes = trimWav(bytes, trimStart, trimEnd);
        const blob = new Blob([trimmedBytes.buffer as ArrayBuffer], { type: mimeType });
        const rawName = fileName ?? `speech-${Date.now()}`;
        const effectiveFilename = rawName.endsWith(".wav") ? rawName : `${rawName}.wav`;
        triggerDownload(blob, effectiveFilename);
        toast.success(m.studio_tts_output_download_success());
        return;
      }
      const result: StudioExecutionResult = { success: true, output };
      await textToSpeechHandler({ result, format: "wav" });
      toast.success(m.studio_tts_output_download_success());
    } catch {
      toast.error(m.studio_tts_output_download_failed());
    }
  }

  const bars = WAVEFORM_BAR_HEIGHTS.map((height, index) => ({
    index,
    height,
    isActive: progressPercent > (index / WAVEFORM_BAR_COUNT) * 100,
  }));
  const orderedBars = isRTL ? [...bars].reverse() : bars;

  const trimStartPercent = effectiveDuration > 0 ? (trimStart / effectiveDuration) * 100 : 0;
  const trimEndPercent = effectiveDuration > 0 ? (trimEnd / effectiveDuration) * 100 : 100;

  const speedLabel = SPEED_STEPS[speedIndex].label;
  const speedValueText = m.studio_tts_player_speed_value({ speed: speedLabel });
  const summaryText = m.studio_tts_output_summary({
    time: formatPlaybackTime(effectiveDuration),
    format: data.format.toUpperCase(),
    model: data.model,
  });

  return (
    <div
      role="region"
      aria-labelledby={HEADING_ID}
      className="flex w-full flex-col gap-cog-4 rounded-xl border border-cog-border bg-cog-surface p-cog-5 shadow-cog-e2"
    >
      <div className="flex items-start justify-between gap-cog-3">
        <div className="flex items-start gap-cog-3">
          <span
            aria-hidden="true"
            className="flex h-cog-6-5 w-cog-6-5 shrink-0 items-center justify-center rounded-lg bg-cog-teal-50 text-cog-teal-700 dark:bg-cog-teal-900/20 dark:text-cog-teal-300"
          >
            <AudioLines aria-hidden="true" className="h-cog-4 w-cog-4" />
          </span>
          <div className="flex flex-col gap-cog-0-5">
            <h2 id={HEADING_ID} className="text-heading-sm text-cog-text-primary">
              {m.studio_tts_output_ready_heading()}
            </h2>
            <p className="text-body-sm text-cog-text-tertiary">{summaryText}</p>
          </div>
        </div>

        {onClose && (
          <button
            type="button"
            aria-label={m.studio_tts_output_close_action()}
            onClick={onClose}
            className={cn(
              "flex h-cog-6 w-cog-6 shrink-0 items-center justify-center rounded-md text-cog-text-tertiary",
              "hover:bg-cog-surface-muted hover:text-cog-text-primary",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus",
            )}
          >
            <X aria-hidden="true" className="h-cog-4 w-cog-4" />
          </button>
        )}
      </div>

      {/* eslint-disable-next-line jsx-a11y/media-has-caption -- no caption track: the synthesized source text (`data.text`) is rendered as a full transcript in the "Script readback" block below, always visible/expandable, adjacent to this player. */}
      <audio
        ref={audioRef}
        data-testid="tts-audio-player"
        src={data.audioSrc}
        onPlay={() => setIsPlaying(true)}
        onPause={() => setIsPlaying(false)}
        onEnded={handleEnded}
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleLoadedMetadata}
      />

      {/* Waveform — decorative only; the seek bar + counters below carry the
          real accessible progress information. The trim handles overlaid on
          top ARE accessible (role="slider", keyboard-operable) — they carry
          their own aria-label/aria-valuetext independent of the waveform's
          own aria-hidden.

          Section 09 "Grab handles + hatched offcuts" (Option A): a tinted
          kept-region band sits behind the bars, the offcuts are hatched
          instead of merely dimmed, wide grab handles carry two grip lines
          each, and a time bubble rides above each handle. `pt-cog-7-5` (44px)
          reserves room for the bubbles so they don't clip against whatever
          sits above the waveform. */}
      <div ref={waveformRef} data-testid="tts-waveform" className="relative pt-cog-7-5">
        {/* Kept-region band (z-0) — renders BEHIND the bars (z-1). */}
        <div
          aria-hidden="true"
          data-testid="tts-trim-band"
          style={{
            insetInlineStart: `${trimStartPercent}%`,
            width: `${trimEndPercent - trimStartPercent}%`,
          }}
          className="pointer-events-none absolute -top-cog-2 -bottom-cog-2 z-0 rounded-md border-y-2 border-cog-teal-600 bg-cog-teal-600/[.12] dark:bg-cog-teal-500/[.15]"
        />

        <div className="relative z-cog-stack-1 flex h-cog-9 items-end gap-cog-0-5" aria-hidden="true">
          {orderedBars.map((bar) => (
            <div
              key={bar.index}
              data-bar-index={bar.index}
              style={{ height: `${bar.height}%` }}
              className={cn(
                "flex-1 rounded-pill transition-colors duration-standard",
                // Unplayed bars are cog-border, not cog-surface-muted: muted
                // lands within ~5% of the card's own cog-surface in light mode
                // (242,240,236 on 255,255,255) and only just above it in dark
                // (34,37,46 on 19,21,26), so a freshly generated clip's
                // waveform was nearly invisible until you played it. One token
                // fixes both modes in the right direction — cog-border is
                // darker than the surface in light (210,218,228) and lighter in
                // dark (71,85,105).
                bar.isActive ? "bg-cog-teal-600" : "bg-cog-border",
                isPlaying && "animate-pulse",
              )}
            />
          ))}
        </div>

        {/* Trimmed-away (offcut) regions render hatched so the kept region
            is visually obvious, independent of the handle positions below.
            The repeating-linear-gradient hatch can't be expressed as a
            cog-* class, so it's the one documented inline-style exception —
            it reads `--cog-text-secondary` (the same CSS variable
            `text-cog-text-secondary` resolves to) rather than a raw hex. */}
        <div
          aria-hidden="true"
          data-testid="tts-trim-dim-start"
          style={{
            insetInlineStart: 0,
            width: `${trimStartPercent}%`,
            backgroundImage:
              "repeating-linear-gradient(45deg, transparent, transparent 4.5px, rgb(var(--cog-text-secondary)) 4.5px, rgb(var(--cog-text-secondary)) 6px)",
          }}
          className="pointer-events-none absolute -top-cog-2 -bottom-cog-2 z-0 rounded-md opacity-70"
        />
        <div
          aria-hidden="true"
          data-testid="tts-trim-dim-end"
          style={{
            insetInlineEnd: 0,
            width: `${100 - trimEndPercent}%`,
            backgroundImage:
              "repeating-linear-gradient(45deg, transparent, transparent 4.5px, rgb(var(--cog-text-secondary)) 4.5px, rgb(var(--cog-text-secondary)) 6px)",
          }}
          className="pointer-events-none absolute -top-cog-2 -bottom-cog-2 z-0 rounded-md opacity-70"
        />

        {/* Section 09's two grab handles are ONE range `Slider`, not two
            widgets: a single Radix Root with a thumb per value, so the start
            and end share one control (and one min-gap invariant) while each
            thumb keeps its own accessible name and mm:ss `aria-valuetext`.

            The Root overlays the waveform with its stock rail and fill
            suppressed (`classNames.track` transparent, `classNames.range`
            hidden) — the tinted kept-region band and the hatched offcuts
            above already draw that region — and `renderThumb` supplies
            Section 09's art: a full-height teal bar with two grip lines, and
            the time bubble riding above it. The bubble lives INSIDE the thumb
            so it tracks the handle's own painted position.

            `h-cog-25` (124px) is the Root's own height, spelled out because a
            Radix thumb's wrapper shrink-wraps its content and so cannot
            inherit it: pt-cog-7-5 (44) + the bars' h-cog-9 (64) + the
            -top-cog-2/-bottom-cog-2 overhang (2x8) = 124.

            Keyboard and pointer handling stay on this component (see
            `handleTrimPointerDown`) — `step` only sets the granularity the
            primitive reports, never the 0.5s arrow/Home/End nudge. */}
        <Slider
          value={[trimStart, trimEnd]}
          min={0}
          max={effectiveDuration}
          step={TRIM_SLIDER_STEP_SECONDS}
          minStepsBetweenThumbs={MIN_TRIM_GAP_STEPS}
          dir={isRTL ? "rtl" : "ltr"}
          thumbLabels={[m.studio_tts_trim_start_label(), m.studio_tts_trim_end_label()]}
          ariaValueText={[formatPlaybackTime(trimStart), formatPlaybackTime(trimEnd)]}
          onKeyDown={handleTrimKeyDown}
          onPointerDown={handleTrimPointerDown}
          className="absolute inset-x-cog-0 -top-cog-2 -bottom-cog-2 z-cog-stack-3"
          classNames={{
            track: "h-full rounded-none bg-transparent",
            range: "hidden",
            thumb: "h-cog-25 cursor-ew-resize",
          }}
          renderThumb={(index) => (
            <>
              <span
                aria-hidden="true"
                data-testid={index === 0 ? "tts-trim-start-bubble" : "tts-trim-end-bubble"}
                className="absolute -top-cog-5 left-1/2 z-cog-stack-4 flex h-cog-4-5 -translate-x-1/2 items-center whitespace-nowrap rounded-base bg-cog-teal-600 px-cog-2 text-micro font-bold tabular-nums text-white dark:text-cog-canvas"
              >
                {formatPlaybackTime(index === 0 ? trimStart : trimEnd)}
              </span>
              <span
                aria-hidden="true"
                className="flex h-full w-cog-3-5 items-center justify-center gap-cog-0-5 rounded-md bg-cog-teal-600 shadow-cog-e2"
              >
                <span data-testid="tts-trim-handle-grip" className="h-cog-3-5 w-cog-0-5 rounded-none bg-white/85 dark:bg-cog-canvas/75" />
                <span data-testid="tts-trim-handle-grip" className="h-cog-3-5 w-cog-0-5 rounded-none bg-white/85 dark:bg-cog-canvas/75" />
              </span>
            </>
          )}
        />
      </div>

      {/* Trim summary + drag hint + reset — always visible so the trimmed
          range is never a hidden state. */}
      <div className="flex items-center justify-between gap-cog-2 text-body-sm text-cog-text-tertiary">
        <span>
          <span>
            {m.studio_tts_trim_duration_summary({
              trimmed: formatPlaybackTime(trimEnd - trimStart),
              total: formatPlaybackTime(effectiveDuration),
            })}
          </span>
          {" · "}
          <span>{m.studio_tts_trim_drag_hint()}</span>
        </span>
        <button
          type="button"
          onClick={handleResetTrim}
          className={cn(
            "rounded-sm text-body-sm font-medium text-cog-teal-700 underline-offset-2 hover:underline dark:text-cog-teal-300",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus",
          )}
        >
          {m.studio_tts_trim_reset_action()}
        </button>
      </div>

      {/* Controls: current time / play-pause / seek bar / total duration / speed */}
      <div className="flex items-center gap-cog-3">
        <span
          data-testid="tts-current-time"
          className="w-cog-7 shrink-0 text-end text-body-sm tabular-nums text-cog-text-secondary"
        >
          {formatPlaybackTime(currentTime)}
        </span>

        <button
          type="button"
          onClick={handlePlayPause}
          aria-label={
            isPlaying ? m.studio_tts_player_pause_label() : m.studio_tts_player_play_label()
          }
          className={cn(
            "flex h-cog-7-5 w-cog-7-5 shrink-0 items-center justify-center rounded-pill",
            "bg-cog-teal-600 text-white",
            "transition-[transform,box-shadow] duration-standard",
            "hover:-translate-y-px hover:shadow-cog-glow-teal dark:hover:shadow-cog-glow-teal-dark",
            "motion-reduce:hover:translate-y-cog-0 active:scale-95 motion-reduce:active:scale-100",
            "focus:outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
          )}
        >
          {isPlaying ? (
            <Pause aria-hidden="true" className="h-cog-4-5 w-cog-4-5" />
          ) : (
            <Play aria-hidden="true" className="h-cog-4-5 w-cog-4-5" />
          )}
        </button>

        {/* Real, keyboard-operable <input type="range"> — `accent-color`
            (Tailwind's `accent-*`) is sufficient to render a filled
            progress segment + a visible circular knob natively in every
            evergreen browser, so no ::-webkit-slider-thumb/::-moz-range-thumb
            pseudo-element overrides (and no custom CSS file) are needed —
            see design.md a11y invariants (real input, native keyboard drag). */}
        <input
          type="range"
          min={0}
          max={effectiveDuration}
          step={0.1}
          value={currentTime}
          onChange={handleSeek}
          aria-label={m.studio_tts_player_seek_label()}
          className="h-cog-1-5 flex-1 cursor-pointer accent-cog-teal-600"
        />

        <span
          data-testid="tts-total-duration"
          className="w-cog-7 shrink-0 text-body-sm tabular-nums text-cog-text-secondary"
        >
          {formatPlaybackTime(effectiveDuration)}
        </span>

        {/* Playback-speed control (NEW) — client-only, cycles the audio
            element's own playbackRate. Distinct from the metadata card's
            fixed "Speed" (generation-time) fact below. */}
        <button
          type="button"
          onClick={handleCycleSpeed}
          aria-label={m.studio_tts_player_speed_action({ speed: speedValueText })}
          className={cn(
            "flex h-cog-6-5 min-w-cog-23 shrink-0 items-center justify-center rounded-pill border border-cog-border",
            "bg-cog-surface text-body-sm font-medium text-cog-text-secondary",
            "hover:bg-cog-surface-muted",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus",
          )}
        >
          {speedValueText}
        </button>
      </div>

      {/* Script readback (NEW) — clamp/expand toggle. */}
      <div className="flex flex-col gap-cog-2 rounded-md border border-cog-border bg-cog-surface-subtle p-cog-4">
        <div className="flex items-center justify-between gap-cog-2">
          <p className="text-body-sm font-medium text-cog-text-primary">
            {m.studio_tts_output_meta_text_label()}
          </p>
          <button
            type="button"
            onClick={() => setScriptExpanded((v) => !v)}
            className={cn(
              "rounded-sm text-body-sm font-medium text-cog-teal-700 underline-offset-2 hover:underline dark:text-cog-teal-300",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus",
            )}
          >
            {scriptExpanded
              ? m.studio_tts_output_script_show_less()
              : m.studio_tts_output_script_show_more()}
          </button>
        </div>
        <p
          className={cn(
            "text-body-sm text-cog-text-secondary",
            !scriptExpanded && "line-clamp-4",
          )}
        >
          {data.text}
        </p>
      </div>

      {/* Metadata — 2-column grid of 6 facts (restyled from the old 5-pair
          <dl>; the raw script text moved to the readback block above). */}
      <dl className="grid grid-cols-2 gap-cog-3 rounded-md border border-cog-border bg-cog-surface-subtle p-cog-4 text-body-sm">
        <MetaFact
          label={m.studio_tts_output_meta_duration_label()}
          value={m.studio_tts_output_meta_duration_value({ seconds: data.duration.toFixed(1) })}
        />
        <MetaFact
          label={m.studio_tts_output_meta_word_count_label()}
          value={String(Math.round(data.wordCount))}
        />
        <MetaFact
          label={m.studio_tts_output_meta_characters_label()}
          value={String(data.text.length)}
        />
        <MetaFact
          label={m.studio_tts_output_meta_speed_label()}
          value={m.studio_tts_output_meta_speed_value()}
        />
        <MetaFact label={m.studio_tts_output_meta_voice_label()} value={data.voice} />
        <MetaFact label={m.studio_tts_output_meta_model_label()} value={data.model} />
      </dl>

      {/* Footer actions — Download (unchanged handler, moved here from the
          header per the redesign) + the new Regenerate action. */}
      <div className="flex items-center justify-end gap-cog-2">
        {onRegenerate && (
          <Button type="button" variant="secondary" size="sm" onClick={onRegenerate}>
            <RotateCcw aria-hidden="true" className="h-cog-4 w-cog-4" />
            {m.studio_tts_output_regenerate_action()}
          </Button>
        )}
        <Button
          type="button"
          variant="teal"
          size="sm"
          aria-label={m.studio_tts_output_download_action()}
          onClick={() => {
            void handleDownload();
          }}
        >
          <Download aria-hidden="true" className="h-cog-4 w-cog-4" />
          {m.studio_tts_output_download_action()}
        </Button>
      </div>
    </div>
  );
}

function MetaFact({ label, value }: { readonly label: string; readonly value: string }): JSX.Element {
  return (
    <div className="flex flex-col gap-cog-1">
      <dt className="font-medium text-cog-text-primary">{label}</dt>
      <dd className="text-cog-text-secondary">{value}</dd>
    </div>
  );
}



